const STORAGE_KEY = 'tavecc-harbor-passport-v1';
const pages = ['sources', 'draft', 'review', 'compliance', 'passport'];
const pageLabels = { sources: 'Source files', draft: 'AI draft', review: 'Human review', compliance: 'Compliance', passport: 'Trust Passport' };
const icons = {
  grid: '<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
  file: '<path d="M7 3h7l5 5v13H7a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2Z"/><path d="M14 3v6h5M9 13h6M9 17h6"/>',
  spark: '<path d="m12 2 1.6 6.4L20 10l-6.4 1.6L12 18l-1.6-6.4L4 10l6.4-1.6L12 2ZM19 18l.5 1.5L21 20l-1.5.5L19 22l-.5-1.5L17 20l1.5-.5L19 18Z"/>',
  check: '<path d="m5 12 4 4L19 6"/>',
  shield: '<path d="M12 2 4 5v6c0 5.2 3.2 8.8 8 11 4.8-2.2 8-5.8 8-11V5l-8-3Z"/><path d="m9 12 2 2 4-4"/>',
  clock: '<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  arrow: '<path d="M4 12h16m-6-6 6 6-6 6"/>',
  down: '<path d="m6 9 6 6 6-6"/>',
  eye: '<path d="M2 12s3.7-6 10-6 10 6 10 6-3.7 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="2.5"/>',
  edit: '<path d="m4 20 4.5-1 10-10a2.1 2.1 0 0 0-3-3l-10 10L4 20ZM14 7l3 3"/>',
  x: '<path d="M5 5 19 19M19 5 5 19"/>',
  upload: '<path d="M12 16V3m-5 5 5-5 5 5M4 16v4h16v-4"/>',
  mail: '<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/>',
  alert: '<path d="M12 3 2 21h20L12 3Z"/><path d="M12 9v5m0 4h.01"/>',
  comment: '<path d="M20 11.5a8.5 8.5 0 0 1-8.5 8.5 9 9 0 0 1-3-.5L3 21l1.5-5.5a9 9 0 0 1-.5-3A8.5 8.5 0 1 1 20 11.5Z"/>',
  download: '<path d="M12 3v13m-5-5 5 5 5-5M4 19v2h16v-2"/>',
  reset: '<path d="M3 11a9 9 0 1 1 2 6M3 4v7h7"/>',
  lock: '<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',
  trend: '<path d="m3 7 6 6 4-4 8 8M15 17h6v-6"/>',
  dots: '<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>'
};
function icon(name, size=18) { return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]}</svg>`; }
function esc(value='') { return String(value).replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch])); }
function freshState() { return { page:'review', selected:'cause', decisions:{}, edits:{}, comments:{}, emailOpened:false, evidenceMarked:false, reviewer:'Sebas', compliance:[false,false,false,false], signedAt:null, signer:'Saday', uploads:[], draftRuns:0, showEmail:false, editing:false, commenting:false }; }
let state;
try { state = { ...freshState(), ...JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}') }; } catch { state = freshState(); }
if (!pages.includes(state.page)) state.page='review';
const save = () => localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
const claims = [
  { id:'cause', num:'01', title:'Root cause of the sales decline', tag:'Key finding', ai:'The 18% sales decline from May to September was primarily driven by reduced marketing spend, which lowered customer demand across the US and Germany.', correction:'The 18% sales decline was primarily driven by supplier delays and stockouts of top-selling products. Marketing spend changed, but the available evidence does not support it as the main cause.', suggestion:'Supplier email · Sep 8' },
  { id:'trend', num:'02', title:'Sales performance', tag:'Supporting fact', ai:'Harbor Home Goods sales declined 18% between May and September across its 40 stores in the US and Germany.', correction:'Harbor Home Goods sales declined 18% between May and September across its 40 stores in the US and Germany.', suggestion:'Monthly sales workbook' },
  { id:'action', num:'03', title:'Recommended next action', tag:'Recommendation', ai:'Increase paid marketing investment by 20% next quarter to recover lost demand and reverse the sales trend.', correction:'Prioritize supplier reliability and replenish top-selling products. Validate on-shelf availability before considering additional marketing investment.', suggestion:'Supplier email + inventory log' }
];
const checks = [
  {title:'Evidence traceability',desc:'Material claims link back to the source files.'},
  {title:'Human correction documented',desc:'The incorrect cause and recommendation were changed.'},
  {title:'Client data handled appropriately',desc:'Only the supplied Harbor case files informed this demo.'},
  {title:'Accountable approver assigned',desc:'A named person signs the final recommendation.'}
];
function status(id) { return state.decisions[id] || 'pending'; }
function countReviewed() { return claims.filter(c => status(c.id) !== 'pending').length; }
function allReviewed() { return countReviewed() === claims.length; }
function allChecks() { return state.compliance.every(Boolean); }
function allCorrected() { return status('cause') === 'revised' && status('action') === 'revised'; }
function canSign() { return allReviewed() && allChecks() && allCorrected() && state.evidenceMarked && state.signer.trim(); }
function currentText(c) { return status(c.id) === 'revised' ? state.edits[c.id] || c.correction : c.ai; }
function badge(id) { const s=status(id); return `<span class="status status-${s}">${s==='pending'?'Needs review':s==='accepted'?'Accepted':'Revised'}</span>`; }
function progressIndex() { return pages.indexOf(state.page); }
function renderNav() { return `<aside class="sidebar">
  <div class="brand"><div class="brand-mark">N<span>✦</span></div><div><strong>THE NEXUS 5</strong><small>CONSULTING GROUP</small></div></div>
  <div class="workspace-label">WORKSPACE <span>DEMO</span></div>
  <div class="workspace-card"><div class="workspace-avatar">H</div><div><strong>Harbor Home Goods</strong><small>Client case · 2026</small></div>${icon('down',15)}</div>
  <div class="nav-heading">WORKFLOW</div>
  <nav aria-label="Workflow">${pages.map((p,i)=>`<button type="button" class="nav-item ${state.page===p?'active':''}" data-page="${p}" ${state.page===p?'aria-current="page"':''}><span class="nav-icon">${icon(['grid','spark','edit','shield','file'][i],18)}</span><span>${pageLabels[p]}</span>${p==='review'?`<span class="nav-count">${countReviewed()}/3</span>`:''}</button>`).join('')}</nav>
  <div class="sidebar-bottom"><div class="sidebar-divider"></div><div class="mission"><div class="mission-icon">${icon('shield',18)}</div><div><strong>AI drafts. Humans decide.</strong><span>Clients see the proof.</span></div></div><button type="button" class="reset-link" data-action="reset">${icon('reset',15)} Reset demo</button></div>
  </aside>`; }
function renderTop() { return `<header class="topbar"><div class="breadcrumb">Client workspace <span>/</span> Harbor Home Goods <span>/</span> <strong>${pageLabels[state.page]}</strong></div><div class="top-actions"><span class="demo-pill"><span></span> Guided demo</span><div class="top-avatar" title="Reviewer">${esc((state.reviewer.trim()||'S').slice(0,1).toUpperCase())}</div></div></header>`; }
function renderStepBar() { return `<div class="stepbar">${pages.map((p,i)=>`<button type="button" data-page="${p}" class="step ${i===progressIndex()?'current':''} ${i<progressIndex()?'done':''}"><span class="step-dot">${i<progressIndex()?icon('check',13):String(i+1).padStart(2,'0')}</span><span>${pageLabels[p]}</span></button>${i<4?'<span class="step-line"></span>':''}`).join('')}</div>`; }
function pageIntro(eyebrow,title,desc,actions='') { return `<div class="page-intro"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="intro-actions">${actions}</div>`:''}</div>`; }
function renderSources() { return `${pageIntro('01 / INPUTS','Source files','A clear record of what entered the analysis—and the evidence the AI overlooked.',`<button class="button button-primary" data-action="trigger-upload">${icon('upload',17)} Add files</button><input id="file-input" type="file" multiple hidden />`)}
 <div class="metric-grid"><div class="metric-card"><span>Case data</span><strong>40 <small>stores</small></strong><p>Across the US and Germany</p></div><div class="metric-card"><span>Sales movement</span><strong class="negative">−18%</strong><p>May through September</p></div><div class="metric-card"><span>Source coverage</span><strong>3 <small>of 4</small></strong><p>Referenced by AI draft</p></div></div>
 <div class="section-head"><div><h2>Harbor data room</h2><p>Sample files prepared for this presentation.</p></div><span class="subtle-pill">4 original sources</span></div>
 <div class="source-list">${[
  ['Monthly sales.xlsx','Sales figures · May–Sep','Referenced','file'],
  ['Marketing spend.xlsx','Campaign spending by month','Referenced','file'],
  ['Inventory status.xlsx','Top products and stock levels','Referenced','file'],
  ['Supplier update.eml','Sep 8 · shipment delays and stockouts','Not cited by AI','mail']
 ].map((f,i)=>`<button class="source-row ${i===3?'source-alert':''}" data-action="${i===3?'open-email':'source-info'}" data-source="${i}" type="button"><span class="source-icon ${i===3?'amber':''}">${icon(f[3],20)}</span><span class="source-main"><strong>${f[0]}</strong><small>${f[1]}</small></span><span class="source-state ${i===3?'missed':''}">${i===3?icon('alert',14):icon('check',14)} ${f[2]}</span><span class="row-chevron">${icon('arrow',17)}</span></button>`).join('')}${state.uploads.map(f=>`<div class="source-row uploaded"><span class="source-icon">${icon('file',20)}</span><span class="source-main"><strong>${esc(f.name)}</strong><small>Added locally · ${esc(f.size)}</small></span><span class="source-state">Demo upload</span></div>`).join('')}</div>
 <div class="info-strip">${icon('lock',17)} Uploaded files stay in this browser. This frontend uses a prepared sample analysis; uploaded files are not sent to an AI model.</div>
 <div class="bottom-next"><div><strong>Next: examine the AI draft</strong><span>See the convincing conclusion before the human review.</span></div><button class="button button-outline" data-page="draft">View AI draft ${icon('arrow',17)}</button></div>`; }
function renderDraft() { return `${pageIntro('02 / AI OUTPUT','AI draft report','A plausible first pass, generated for the demo from only part of the evidence.',`<button class="button button-outline" data-action="rerun">${icon('spark',17)} Regenerate sample draft</button>`)}
 <div class="notice notice-amber">${icon('alert',20)} <div><strong>One source was missed</strong><span>The draft does not cite the supplier email. The recommendation may be materially wrong.</span></div><button data-action="open-email">Inspect email ${icon('arrow',15)}</button></div>
 <div class="report-paper"><div class="report-meta"><span>THE NEXUS 5 / CLIENT ANALYSIS</span><span>DRAFT · NOT FOR CLIENT DISTRIBUTION</span></div><div class="report-heading"><div><div class="eyebrow">Harbor Home Goods</div><h2>Sales decline assessment</h2><p>May–September 2026 · US and Germany</p></div><div class="draft-stamp">AI DRAFT<br/><small>Human review required</small></div></div>
 <div class="report-summary"><span>EXECUTIVE SUMMARY</span><p>Sales fell 18% during the period. The draft attributes this decline to lower marketing investment and recommends increasing paid spend. This interpretation requires source verification.</p></div>
 ${claims.map(c=>`<section class="report-section"><div class="report-section-num">${c.num}</div><div><h3>${c.title}</h3><p>${c.ai}</p><div class="citation">${icon('file',14)} ${c.id==='cause'?'Sales workbook + marketing spend':c.suggestion}</div></div></section>`).join('')}</div>
 <div class="bottom-next"><div><strong>Human review starts here</strong><span>Challenge claims against all four sources.</span></div><button class="button button-primary" data-page="review">Review the report ${icon('arrow',17)}</button></div>`; }
function renderReview() { const c=claims.find(x=>x.id===state.selected)||claims[0]; return `${pageIntro('03 / HUMAN DECISION','Review the report','Treat each finding like a change request: inspect evidence, accept it, or replace it with a documented correction.',`<div class="review-progress">${icon('check',16)} <strong>${countReviewed()} of 3</strong> sections reviewed</div>`)}
 <div class="review-layout"><div class="review-main"><div class="pane-title"><div><h2>AI report sections</h2><p>Select a section to inspect its claim.</p></div><span class="subtle-pill">3 findings</span></div>
 ${claims.map(item=>`<button type="button" class="claim-card ${state.selected===item.id?'selected':''}" data-select="${item.id}"><div class="claim-top"><span class="claim-number">${item.num}</span><span class="claim-tag">${item.tag}</span>${badge(item.id)}</div><h3>${item.title}</h3><p>${esc(currentText(item))}</p><div class="claim-foot"><span>${icon('file',14)} ${item.id==='cause'?'AI cited: sales + marketing':item.id==='action'?'AI cited: draft analysis':'AI cited: monthly sales'}</span>${state.comments[item.id]?`<span>${icon('comment',14)} 1 comment</span>`:''}</div></button>`).join('')}
 <div class="reviewer-row"><label for="reviewer-name">Reviewed by</label><input id="reviewer-name" aria-label="Reviewer name" value="${esc(state.reviewer)}" maxlength="50" placeholder="Your name" /><span>Changes are saved in this browser.</span></div></div>
 <div class="review-aside"><div class="pane-title"><div><h2>Review detail</h2><p>Section ${c.num} · ${c.tag}</p></div>${icon('dots',20)}</div>
 <div class="detail-card"><div class="detail-label">AI ASSERTION <span class="red-dot"></span></div><div class="diff-old">${esc(c.ai)}</div>
 ${status(c.id)==='revised'?`<div class="detail-label green-label">HUMAN CORRECTION <span class="green-dot"></span></div><div class="diff-new">${esc(state.edits[c.id]||c.correction)}</div>`:''}
 ${state.comments[c.id]?`<div class="saved-comment"><div>${icon('comment',15)} REVIEWER NOTE</div><p>${esc(state.comments[c.id])}</p></div>`:''}
 <div class="detail-actions"><button class="button button-soft" data-action="accept" ${status(c.id)==='accepted'?'disabled':''}>${icon('check',16)} ${status(c.id)==='accepted'?'Accepted':'Accept section'}</button><button class="button button-danger" data-action="reject">${icon('edit',16)} ${status(c.id)==='revised'?'Edit correction':'Reject & correct'}</button></div>
 <button class="text-action" data-action="comment">${icon('comment',15)} ${state.comments[c.id]?'Edit reviewer note':'Add reviewer note'}</button>
 ${state.editing?`<div class="editor"><label for="correction-text">Replacement text</label><textarea id="correction-text" rows="5">${esc(state.edits[c.id]||c.correction)}</textarea><label for="correction-note">Why this changed</label><textarea id="correction-note" rows="3" placeholder="Point to the evidence and explain the decision.">${esc(state.comments[c.id]||'Supplier email confirms shipment delays and stockouts. The draft overlooked this evidence.')}</textarea><div class="editor-actions"><button class="button button-primary" data-action="save-correction">Save correction</button><button class="button button-plain" data-action="cancel-edit">Cancel</button></div></div>`:''}
 ${state.commenting&&!state.editing?`<div class="editor"><label for="comment-text">Reviewer note</label><textarea id="comment-text" rows="3" placeholder="Add context for the audit trail.">${esc(state.comments[c.id]||'')}</textarea><div class="editor-actions"><button class="button button-primary" data-action="save-comment">Save note</button><button class="button button-plain" data-action="cancel-comment">Cancel</button></div></div>`:''}</div>
 <div class="evidence-card"><div class="evidence-head"><div class="evidence-icon">${icon('mail',18)}</div><div><strong>Overlooked evidence</strong><span>Supplier update · September 8</span></div><span class="attention-dot"></span></div><p>One email explains why key products were unavailable during the sales decline.</p><button class="evidence-link" data-action="open-email">${state.emailOpened?'Reopen supplier email':'Open supplier email'} ${icon('arrow',16)}</button>${state.evidenceMarked?`<div class="evidence-marked">${icon('check',14)} Added to human review trail</div>`:''}</div></div></div>
 <div class="bottom-next"><div><strong>${allReviewed()?'Review complete':'Resolve all three sections'}</strong><span>${allReviewed()?'Move to compliance sign-off.':'Each finding needs a human decision before sign-off.'}</span></div><button class="button ${allReviewed()?'button-primary':'button-outline'}" data-page="compliance">Compliance check ${icon('arrow',17)}</button></div>`; }
function renderCompliance() { return `${pageIntro('04 / GOVERNANCE','Compliance sign-off','A second human checks that the final recommendation is supported and accountable.')}
 <div class="compliance-grid"><div class="compliance-panel"><div class="section-head"><div><h2>Release checklist</h2><p>Confirm each control before issuing the Passport.</p></div><span class="subtle-pill">${state.compliance.filter(Boolean).length}/4 complete</span></div>
 ${checks.map((c,i)=>`<label class="check-row ${state.compliance[i]?'checked':''}"><input type="checkbox" data-check="${i}" ${state.compliance[i]?'checked':''}/><span class="custom-check">${icon('check',14)}</span><span><strong>${c.title}</strong><small>${c.desc}</small></span></label>`).join('')}
 <div class="signer-field"><label for="signer-name">Compliance approver</label><input id="signer-name" value="${esc(state.signer)}" maxlength="50" placeholder="Approver name" /></div>
 ${!state.evidenceMarked?`<div class="gate-message">${icon('mail',17)} Open the overlooked supplier email and add it to the human review trail.</div>`:''}
 ${!allCorrected()?`<div class="gate-message">${icon('alert',17)} Correct both the root cause and recommendation in human review before signing.</div>`:''}
 ${!allReviewed()?`<div class="gate-message">${icon('clock',17)} ${3-countReviewed()} report section${3-countReviewed()===1?'':'s'} still need a decision.</div>`:''}
 <button class="button button-primary sign-button" data-action="sign" ${canSign()?'':'disabled'}>${icon('shield',18)} ${state.signedAt?'Update sign-off':'Sign off and issue Passport'}</button></div>
 <div class="compliance-side"><div class="policy-card"><div class="policy-icon">${icon('shield',22)}</div><h3>AI drafts.<br/>Humans decide.</h3><p>Nothing goes to a client without a named reviewer and compliance approval.</p><div class="policy-divider"></div><div class="policy-step"><span>01</span><div><strong>Consultant review</strong><small>${countReviewed()} of 3 findings decided</small></div>${countReviewed()===3?icon('check',16):icon('clock',16)}</div><div class="policy-step"><span>02</span><div><strong>Compliance approval</strong><small>${state.signedAt?'Signed by '+esc(state.signer):'Pending sign-off'}</small></div>${state.signedAt?icon('check',16):icon('clock',16)}</div><div class="policy-step"><span>03</span><div><strong>Client Passport</strong><small>Proof of the review trail</small></div>${state.signedAt?icon('check',16):icon('clock',16)}</div></div></div></div>`; }
function renderPassport() { const signed=Boolean(state.signedAt); return `${pageIntro('05 / CLIENT TRANSPARENCY','AI Trust Passport','One page that shows what AI drafted, what people changed, and who approved the final advice.',`<button class="button button-outline print-btn" data-action="print">${icon('download',17)} Print / save PDF</button>`)}
 <div class="passport-status ${signed?'issued':''}">${icon(signed?'check':'clock',18)} <div><strong>${signed?'Passport issued':'Preview · sign-off pending'}</strong><span>${signed?'Ready to accompany the client report.':'Complete the review and compliance checklist to issue this Passport.'}</span></div>${signed?`<span class="passport-id">ATP–HHG–2026–01</span>`:''}</div>
 <article class="passport-paper"><div class="passport-top"><div class="passport-logo"><span class="passport-symbol">✦</span><span>THE NEXUS 5<br/><small>CONSULTING GROUP</small></span></div><span class="passport-document">AI TRUST PASSPORT<br/><small>CLIENT COPY</small></span></div><div class="passport-title"><div><div class="eyebrow">HARBOR HOME GOODS / SEPTEMBER 2026</div><h2>The recommendation,<br/><em>with a clear review trail.</em></h2></div><div class="seal">${icon('shield',31)}<span>HUMAN<br/>VERIFIED</span></div></div>
 <div class="passport-grid"><div><span class="mini-label">AI TOOL & ROLE</span><strong>Simulated AI draft</strong><p>Prepared first-pass analysis for this demo. A human consultant reviews material claims before any recommendation can be issued.</p></div><div><span class="mini-label">DATA CONSIDERED</span><strong>${state.evidenceMarked?'4':'3 of 4'} case sources reviewed</strong><p>Sales, marketing spend, inventory status, and a supplier email. The AI draft cited three; ${state.evidenceMarked?'the human reviewer identified the overlooked email.':'the supplier email still needs human review.'}</p></div></div>
 <div class="passport-change"><div class="mini-label">THE MATERIAL CHANGE</div><div class="change-cols"><div><span class="change-tag ai-tag">AI DRAFT</span><p>${esc(claims[0].ai)}</p></div><div><span class="change-tag human-tag">HUMAN DECISION</span><p>${esc(status('cause')==='revised'?currentText(claims[0]):'Pending human correction')}</p></div></div><div class="change-note">${icon('mail',16)} Supplier update, Sep 8: late shipments left top products out of stock.</div></div>
 <div class="passport-final"><div class="mini-label">${signed?'FINAL RECOMMENDATION':'RECOMMENDATION STATUS'}</div><p>${esc(status('action')==='revised'?currentText(claims[2]):'Pending human review')}</p></div>
 <div class="passport-signatures"><div><span class="mini-label">REVIEWED BY</span><strong>${esc(state.reviewer.trim()||'Pending')}</strong><small>Consultant · finding-level decisions</small></div><div><span class="mini-label">COMPLIANCE APPROVAL</span><strong>${signed?esc(state.signer.trim()):'Pending sign-off'}</strong><small>${signed?new Date(state.signedAt).toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'}):'Release checklist incomplete'}</small></div><div><span class="mini-label">REVIEWED SECTIONS</span><strong>${countReviewed()} / 3</strong><small>With decisions and notes</small></div></div><div class="passport-footer"><strong>AI drafts. Humans decide. Clients see the proof.</strong><span>AI Trust Passport · Demonstration</span></div></article>
 <div class="comparison"><div class="section-head"><div><h2>The difference clients can see</h2><p>Same case, two ways to deliver the advice.</p></div></div><div class="comparison-grid"><div><span class="comparison-kicker">WITHOUT PASSPORT</span><h3>“Increase marketing spend.”</h3><p>Confident recommendation. No visible source trail, reviewer, or correction.</p></div><div class="comparison-with"><span class="comparison-kicker">WITH PASSPORT</span><h3>“Fix stock availability first.”</h3><p>Evidence identified, AI error corrected, named people accountable.</p></div></div></div>`; }
function renderEmail() { return `<div class="modal-backdrop" data-action="close-email"><div class="email-modal" role="dialog" aria-modal="true" aria-labelledby="email-title"><div class="email-toolbar"><span>${icon('mail',18)} SOURCE DOCUMENT · 04/04</span><button class="icon-button" data-action="close-email" aria-label="Close email">${icon('x',20)}</button></div><div class="email-content"><div class="email-subject"><div class="eyebrow">SUPPLIER UPDATE</div><h2 id="email-title">Shipment delay affecting top sellers</h2></div><div class="email-headers"><div><span>From</span><strong>Maya Chen · Northline Suppliers</strong></div><div><span>To</span><strong>Harbor merchandising team</strong></div><div><span>Date</span><strong>September 8, 2026</strong></div></div><div class="email-body"><p>Hi team,</p><p>We need to confirm that the late August shipment of your top-selling home storage and kitchen lines is delayed. Several high-volume SKUs have been <mark>out of stock across US and German stores since mid-August</mark>.</p><p>The delay is on our side. We now expect replenishment in late September. Please factor this into the recent sales decline before changing demand-generation plans.</p><p>Best,<br/>Maya</p></div><div class="email-insight">${icon('alert',18)} <span><strong>Why it matters</strong>The email points to supply and product availability, while the AI draft blamed lower customer demand.</span></div><div class="email-actions"><button class="button button-primary" data-action="mark-evidence">${icon('check',17)} Use in human review</button><button class="button button-outline" data-action="close-email">Close</button></div></div></div></div>`; }
function render() { const app=document.getElementById('app'); app.innerHTML=`<div class="shell">${renderNav()}<div class="main-shell">${renderTop()}<main class="main-content">${renderStepBar()}${({sources:renderSources,draft:renderDraft,review:renderReview,compliance:renderCompliance,passport:renderPassport})[state.page]()}</main></div></div>${state.showEmail?renderEmail():''}<div id="toast" class="toast" role="status" aria-live="polite"></div>`; document.title=`${pageLabels[state.page]} · AI Trust Passport`; }
function notify(msg) { const el=document.getElementById('toast'); if(!el)return; el.textContent=msg; el.classList.add('visible'); clearTimeout(notify.timer); notify.timer=setTimeout(()=>el.classList.remove('visible'),3300); }
function navigate(page) { if(!pages.includes(page))return; state.page=page; state.editing=false; state.commenting=false; state.showEmail=false; save(); render(); window.scrollTo({top:0,behavior:'smooth'}); }
document.addEventListener('click', e=>{ const pageButton=e.target.closest('[data-page]'); if(pageButton){navigate(pageButton.dataset.page);return;} const select=e.target.closest('[data-select]'); if(select){state.selected=select.dataset.select;state.editing=false;state.commenting=false;save();render();return;} const action=e.target.closest('[data-action]'); if(!action)return; const id=action.dataset.action;
 if(id==='trigger-upload'){document.getElementById('file-input')?.click();return;}
 if(id==='source-info'){notify('This source is part of the prepared Harbor case.');return;}
 if(id==='open-email'){state.showEmail=true;state.emailOpened=true;save();render();return;}
 if(id==='close-email'){if(action.classList.contains('modal-backdrop') && e.target!==action)return;state.showEmail=false;save();render();return;}
 if(id==='mark-evidence'){state.showEmail=false;state.emailOpened=true;state.evidenceMarked=true;state.page='review';state.selected='cause';save();render();notify('Supplier email added to the human review trail.');return;}
 if(id==='accept'){state.decisions[state.selected]='accepted';state.editing=false;state.commenting=false;state.signedAt=null;save();render();notify('Section accepted.');return;}
 if(id==='reject'){state.editing=true;state.commenting=false;render();document.getElementById('correction-text')?.focus();return;}
 if(id==='cancel-edit'){state.editing=false;render();return;}
 if(id==='save-correction'){const v=document.getElementById('correction-text')?.value.trim();if(!v){notify('Add replacement text first.');return;}state.edits[state.selected]=v;state.comments[state.selected]=document.getElementById('correction-note')?.value.trim()||'';state.decisions[state.selected]='revised';state.editing=false;state.signedAt=null;save();render();notify('Human correction saved to the review trail.');return;}
 if(id==='comment'){state.commenting=true;state.editing=false;render();document.getElementById('comment-text')?.focus();return;}
 if(id==='cancel-comment'){state.commenting=false;render();return;}
 if(id==='save-comment'){state.comments[state.selected]=document.getElementById('comment-text')?.value.trim()||'';state.commenting=false;save();render();notify('Reviewer note saved.');return;}
 if(id==='sign'){if(!canSign()){notify('Finish the review and checklist before signing.');return;}state.signedAt=new Date().toISOString();state.page='passport';save();render();window.scrollTo(0,0);notify('Passport issued with human and compliance approval.');return;}
 if(id==='print'){window.print();return;}
 if(id==='rerun'){state.draftRuns++;save();notify('Sample AI draft regenerated. It still omits the supplier email.');return;}
 if(id==='reset'){state=freshState();save();render();notify('Demo reset to its starting state.');return;}
});
document.addEventListener('change', e=>{ if(e.target.matches('[data-check]')){state.compliance[Number(e.target.dataset.check)]=e.target.checked;state.signedAt=null;save();render();} if(e.target.id==='file-input'){const files=Array.from(e.target.files||[]);state.uploads.push(...files.map(f=>({name:f.name,size:f.size<1024*1024?`${Math.max(1,Math.round(f.size/1024))} KB`:`${(f.size/1024/1024).toFixed(1)} MB`})));save();render();notify(`${files.length} file${files.length===1?'':'s'} added locally.`);}});
document.addEventListener('input',e=>{if(e.target.id==='reviewer-name'){state.reviewer=e.target.value;state.signedAt=null;save();}if(e.target.id==='signer-name'){state.signer=e.target.value;state.signedAt=null;save();const btn=document.querySelector('.sign-button');if(btn)btn.disabled=!canSign();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.showEmail){state.showEmail=false;save();render();}});
render();
